struct PreTradeRiskLimits {
    double max_order_notional;
    double max_gross_position;
    double max_price_collar_pct;
    int max_order_velocity_per_sec;
};

class SEC15c35RiskGate {
public:
    explicit SEC15c35RiskGate(PreTradeRiskLimits limits) : limits_(limits) {}

    bool validate_order(const std::string& symbol, double price, int qty, double ref_price) {
        double notional = price * qty;
        if (notional > limits_.max_order_notional) {
            std::cout << "[15c3-5 REJECT] Single order notional $" << std::fixed << std::setprecision(2) << notional 
                      << " exceeds limit $" << limits_.max_order_notional << "\n";
            return false;
        }
        double deviation = std::abs(price - ref_price) / ref_price;
        if (deviation > limits_.max_price_collar_pct) {
            std::cout << "[15c3-5 REJECT] Price collar deviation " << (deviation * 100.0) << "% exceeds limit!\n";
            return false;
        }
        return true;
    }
private:
    PreTradeRiskLimits limits_;
};

int main() {
    std::cout << "=== SEC RULE 15c3-5 HARDWARE PRE-TRADE RISK GATE ===\n";
    SEC15c35RiskGate gate({1000000.0, 5000000.0, 0.05, 5000});
    bool ok1 = gate.validate_order("SPY", 500.00, 1000, 500.00); // $500k -> OK
    std::cout << "Order 1 Approved: " << (ok1 ? "TRUE" : "FALSE") << "\n";
    bool ok2 = gate.validate_order("SPY", 550.00, 1000, 500.00); // 10% collar -> REJECT
    std::cout << "Order 2 Approved: " << (ok2 ? "TRUE" : "FALSE") << "\n";
    return 0;
}

